 static byte[]utf(String s)throws Exception{return s.getBytes("UTF-8");}
 static void put(ZipOutputStream z,String name,byte[]data,boolean stored)throws Exception{ZipEntry e=new ZipEntry(name);if(stored){CRC32 crc=new CRC32();crc.update(data);e.setMethod(ZipEntry.STORED);e.setSize(data.length);e.setCompressedSize(data.length);e.setCrc(crc.getValue());}z.putNextEntry(e);z.write(data);z.closeEntry();}
 File pdf(File folder,Host host)throws Exception{
  File target=new File(folder,"document.pdf");PdfDocument doc=new PdfDocument();PdfDocument.Page page=null;int pageIndex=0;float y=40;TextPaint paint=new TextPaint(Paint.ANTI_ALIAS_FLAG);paint.setColor(Color.BLACK);paint.setTextSize(12);
  try{for(Block b:blocks){host.check();if(page==null){page=doc.startPage(new PdfDocument.PageInfo.Builder(595,842,++pageIndex).create());y=40;}
    if(b.page){doc.finishPage(page);page=null;continue;}
    if(b.image!=null){Bitmap image=BitmapFactory.decodeByteArray(b.image,0,b.image.length);try{float scale=Math.min(515f/image.getWidth(),750f/image.getHeight());float w=image.getWidth()*scale,h=image.getHeight()*scale;if(y+h>802&&y>40){doc.finishPage(page);page=doc.startPage(new PdfDocument.PageInfo.Builder(595,842,++pageIndex).create());y=40;}page.getCanvas().drawBitmap(image,null,new RectF(40,y,40+w,y+h),new Paint(Paint.FILTER_BITMAP_FLAG));y+=h+10;}finally{image.recycle();}}
    else{StaticLayout layout=new StaticLayout(b.text,paint,515,Layout.Alignment.ALIGN_NORMAL,1.2f,0,false);int first=0;while(first<layout.getLineCount()){int top=layout.getLineTop(first),last=first;while(last<layout.getLineCount()&&layout.getLineBottom(last)-top<=802-y)last++;if(last==first){doc.finishPage(page);page=doc.startPage(new PdfDocument.PageInfo.Builder(595,842,++pageIndex).create());y=40;continue;}Canvas c=page.getCanvas();c.save();c.translate(40,y-top);c.clipRect(0,top,515,layout.getLineBottom(last-1));layout.draw(c);c.restore();y+=layout.getLineBottom(last-1)-top;first=last;if(first<layout.getLineCount()){doc.finishPage(page);page=doc.startPage(new PdfDocument.PageInfo.Builder(595,842,++pageIndex).create());y=40;}}y+=8;}
   }if(page!=null)doc.finishPage(page);FileOutputStream out=new FileOutputStream(target);try{doc.writeTo(out);}finally{out.close();}
  }finally{doc.close();}if(!text().trim().isEmpty())DocumentEngine.preserveLogicalText(target,text());return target;
 }
